import { ImageResponse } from "@vercel/og";
import { redis, KEY } from "@/lib/redis";

export const runtime = "edge";

interface Reminder {
  id: string;
  text: string;
  done: boolean;
  order: number;
}

// ── Canvas ───────────────────────────────────────────────────────────────────
const W = 1179;
const H = 2556;

// ── Palette ──────────────────────────────────────────────────────────────────
const ORANGE = "#FF693C";
const WHITE  = "#FFFFFF";
const DONE_C = "#484848";

// ── Safe zone — below iPhone 14 Pro clock, above home indicator ───────────────
const SAFE_TOP    = 900;
const SAFE_BOTTOM = 2300;
const SAFE_H      = SAFE_BOTTOM - SAFE_TOP; // 1400px

// ── Layout constants ──────────────────────────────────────────────────────────
const SIDE_PAD = 72;
const BAR_W    = 4;
const BAR_MR   = 20;
const NUM_W    = 64;
const COL_GAP  = 22;
const TEXT_W   = W - 2 * SIDE_PAD - BAR_W - BAR_MR - NUM_W - COL_GAP; // 921px

const HEADER_H = 90;
const FOOTER_H = 55;

const FONT_MAX    = 118;
const FONT_MIN    = 34;
const CHAR_RATIO  = 0.64;
const ITEM_RATIO  = 1.38;

// ── Inlined assets ────────────────────────────────────────────────────────────
const FONT_B64 = "";

const SIGN_B64 = "";

function b64ToBuffer(b64: string): ArrayBuffer {
  const binary = atob(b64);
  const bytes  = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes.buffer;
}

const fontData = b64ToBuffer(FONT_B64);

// ── Route ────────────────────────────────────────────────────────────────────
export async function GET() {
  const data = await redis.get<Reminder[]>(KEY);
  const all  = (data ?? []).sort((a, b) => a.order - b.order);

  const sorted  = [...all.filter(r => !r.done), ...all.filter(r => r.done)];
  const pending = sorted.filter(r => !r.done);
  const N       = sorted.length;

  let fontSize = FONT_MAX;
  if (N > 0) {
    const itemArea = SAFE_H - HEADER_H - FOOTER_H;
    const F_height = Math.floor(itemArea / (N * ITEM_RATIO));
    const maxChars = Math.max(...sorted.map(r => r.text.length), 1);
    const F_width  = Math.floor(TEXT_W / (maxChars * CHAR_RATIO));
    fontSize = Math.max(FONT_MIN, Math.min(F_height, F_width, FONT_MAX));
  }

  const ITEM_H = Math.round(fontSize * ITEM_RATIO);
  const NUM_PX = Math.max(26, Math.round(fontSize * 0.35));

  const blockH = HEADER_H + N * ITEM_H + FOOTER_H;
  const topPad = Math.max(
    SAFE_TOP,
    Math.min(SAFE_TOP + Math.floor((SAFE_H - blockH) / 2), SAFE_BOTTOM - blockH),
  );

  const now     = new Date();
  const timeStr = now.toLocaleTimeString("en-US", { hour: "2-digit", minute: "2-digit" });
  const textLS  = fontSize > 72 ? "-0.04em" : fontSize > 50 ? "-0.02em" : "-0.01em";

  return new ImageResponse(
    (
      <div style={{ width: W, height: H, background: "#000", display: "flex", fontFamily: "Inter", position: "relative" }}>

        <div style={{
          position: "absolute", top: 0, left: 0, right: 0, bottom: 0, display: "flex",
          background: "linear-gradient(180deg, #000000 0%, #060606 45%, #030303 70%, #000000 100%)",
        }} />

        <div style={{
          display: "flex", flexDirection: "column",
          paddingTop: topPad, paddingLeft: SIDE_PAD, paddingRight: SIDE_PAD,
          width: "100%", position: "relative",
        }}>

          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", height: 52, marginBottom: 14 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
              <div style={{ width: 8, height: 8, background: ORANGE, borderRadius: "50%", display: "flex", flexShrink: 0 }} />
              <span style={{ fontSize: 28, color: ORANGE, letterSpacing: "0.40em", fontWeight: 700 }}>
                REMINDERS
              </span>
            </div>
            <span style={{ fontSize: 28, color: pending.length > 0 ? ORANGE : "#2e2e2e", letterSpacing: "0.08em", fontWeight: 700 }}>
              {pending.length > 0 ? `${pending.length} left` : N > 0 ? "all done  ✓" : ""}
            </span>
          </div>

          <div style={{ height: 1, background: ORANGE, opacity: 0.2, marginBottom: 24, display: "flex" }} />

          {N === 0 && (
            <div style={{ display: "flex", alignItems: "center", height: 200 }}>
              <span style={{ fontSize: 96, color: ORANGE, fontWeight: 700, letterSpacing: "-0.04em" }}>all set.</span>
            </div>
          )}

          {sorted.map((r, i) => (
            <div key={r.id} style={{
              display: "flex", alignItems: "center", height: ITEM_H,
              borderBottom: i < N - 1 ? "1px solid #0A0A0A" : "none",
            }}>
              <div style={{
                width: BAR_W, height: Math.round(ITEM_H * 0.52),
                background: r.done ? "transparent" : ORANGE,
                borderRadius: 2, flexShrink: 0, marginRight: BAR_MR,
              }} />

              <span style={{
                fontSize: NUM_PX, color: ORANGE, fontWeight: 700,
                letterSpacing: "0.06em", width: NUM_W, textAlign: "right",
                flexShrink: 0, opacity: r.done ? 0.45 : 1, lineHeight: 1,
              }}>
                {String(i + 1).padStart(2, "0")}
              </span>

              <div style={{ width: COL_GAP, flexShrink: 0 }} />

              <span style={{
                fontSize: fontSize, color: r.done ? DONE_C : WHITE, fontWeight: 700,
                letterSpacing: textLS, textDecoration: r.done ? "line-through" : "none",
                flex: 1, lineHeight: 1.05, overflow: "hidden",
              }}>
                {r.text}
              </span>
            </div>
          ))}

          <div style={{
            display: "flex", justifyContent: "space-between", alignItems: "flex-end",
            marginTop: 20, height: FOOTER_H - 20,
          }}>
            <span style={{ fontSize: 18, color: "#1c1c1c", letterSpacing: "0.08em" }}>{timeStr}</span>
            <img
              src={`data:image/png;base64,${SIGN_B64}`}
              style={{ width: 190, height: 122, opacity: 0.72 }}
            />
          </div>

        </div>
      </div>
    ),
    { width: W, height: H, fonts: [{ name: "Inter", data: fontData, style: "normal", weight: 700 }] },
  );
}
